    // ──────────────────────────────────────────────
    // Hardware
    // ──────────────────────────────────────────────

    public function test_hardware_read_denied_without_ability(): void
    {
        $token = $this->createTokenWithAbilities(['units:read']);
        $this->apiGet('/api/hardware', $token)->assertForbidden();
